<script setup lang="ts">import {ref,computed,watch} from 'vue';import type {Workspace} from '../stores/workspace';import type {Run} from '../types/domain';import {create} from '../api/studies';import * as runs from '../api/runs';import {useAction} from '../hooks/useAction';import Heading from '../components/common/Heading.vue';import Notice from '../components/common/Notice.vue';import Empty from '../components/common/Empty.vue';import Status from '../components/common/Status.vue';import PolicyStrip from '../components/PolicyStrip.vue';const props=defineProps<{data:Workspace;canWrite:boolean;refresh:()=>Promise<void>}>();const emit=defineEmits<{open:[string]}>();const name=ref('足迹五组·新包络研究'),sid=ref('demo-survey'),pid=ref('demo-policy'),groups=ref<string[]>([]);const survey=computed(()=>props.data.surveys.find(s=>s.id===sid.value)||props.data.surveys[0]);watch(()=>survey.value?.id,()=>groups.value=survey.value?.groups.map(g=>g.group_id)||[],{immediate:true});const{busy,error,notice,act}=useAction();const runOf=(studyId:string):Run|undefined=>props.data.runs.find(r=>r.study_id===studyId);const inFlight=(r?:Run)=>!!r&&(r.status==='queued'||r.status==='running');</script><template><Heading index="04 / FROZEN STUDIES" title="选择点组，冻结完整来源。" detail="选择仅决定本次计算范围；快照仍锁定完整原始测组、去重规则与方向参数，不因切换组删除源数据。同一研究的并发提交合并为同一次计算，失败可重试，成功结果与复核归档不被覆盖。"/><section v-if="canWrite" class="form-section"><form class="form-grid" @submit.prevent="act(async()=>{await create({name,survey_id:survey!.id,policy_id:pid,group_ids:groups});await refresh()},'研究快照已冻结，可提交后台包络比较')"><label>包络研究名称<input aria-label="包络研究名称" required v-model="name"/></label><label>研究测组<select aria-label="研究测组" v-model="sid"><option v-for="s in data.surveys" :key="s.id" :value="s.id">{{s.name}}</option></select></label><label>研究边界口径<select aria-label="研究边界口径" v-model="pid"><option v-for="p in data.policies" :key="p.id" :value="p.id">{{p.name}}</option></select></label><div class="group-checks"><span>本次计算点组</span><label v-for="g in survey?.groups" :key="g.group_id"><input type="checkbox" :aria-label="'选择'+g.group_id" :value="g.group_id" v-model="groups"/>{{g.group_id}} {{g.name}}</label></div><button class="primary" :disabled="busy">冻结包络研究</button></form><Notice :error="error" :notice="notice"/></section><Empty v-if="!data.studies.length">先导入local_m测组、保存去重规则，再选择至少一个点组冻结研究。</Empty><article v-for="s in data.studies" :key="s.id" class="scenario-row"><div><p class="eyebrow">SNAPSHOT / 源{{s.snapshot.survey.groups.length}}组 / 本次{{s.group_ids.join(', ')}}</p><h2>{{s.name}}</h2><p>{{s.snapshot.survey.source}}</p><PolicyStrip :policy="s.snapshot.policy"/></div><div class="run-actions"><template v-if="!runOf(s.id)"><button v-if="canWrite" :disabled="busy" @click="act(async()=>{const r=await runs.create({study_id:s.id});await refresh();emit('open',r.id)},'包络比较已提交Redis，同一研究重复提交将合并到本次计算')">运行凸包与定向框 →</button><small>尚未运行</small></template><template v-else><div class="run-line"><Status :value="runOf(s.id)!.status"/><small>第 {{runOf(s.id)!.attempts}} 次尝试 · {{runOf(s.id)!.id.slice(0,12)}}</small></div><p v-if="runOf(s.id)!.status==='failed'" role="alert" class="notice error run-error">失败原因：{{runOf(s.id)!.error||'未知错误'}}<br/>原因已保留，可重试重算。</p><button v-if="runOf(s.id)!.status==='failed'&&canWrite" :disabled="busy" @click="act(async()=>{const r=await runs.retry(runOf(s.id)!.id);await refresh();emit('open',r.id)},'已重新入队，失败原因保留至重算成功')">重试本次计算 ↻</button><button v-else :disabled="inFlight(runOf(s.id))" @click="emit('open',runOf(s.id)!.id)">查看本次任务 →</button><small v-if="inFlight(runOf(s.id))">计算进行中，重复提交不会产生新任务</small><small v-else-if="runOf(s.id)!.status==='completed'">成功结果与复核归档受保护，不会被覆盖</small></template></div></article></template>